{
  "causes": [
    {
      "cause": "The v2 build consumed the whole of 18 Oct; deploy, deck, and video were rushed or missed, so the entry failed the Cup's mandatory deliverables despite better features.",
      "earliest_signal": "No Cloud Run URL by midday 18 Oct Colombo time while v2 tickets are still open.",
      "prevention": "Timebox v2 to a hard cut-off; deploy the v1 build first as a safety net the moment billing opens, then redeploy v2 when it is green.",
      "interrogation_question": "If v2 is not green by a cut-off hour on 18 Oct, do we submit v1 (already accepted) instead?"
    },
    {
      "cause": "build_history.py mis-parsed wrapped item descriptions and the loyalty-points figure that prints beside line 5, so quantities and amounts in purchase-history.json were wrong and cadence dates were off.",
      "earliest_signal": "Parsed line amounts per bill do not sum to the bill's Total Gross Amount.",
      "prevention": "Fail the build when any bill's parsed lines do not sum to its gross total within rounding; test that per bill.",
      "interrogation_question": "Is a per-bill sum check against Total Gross Amount an acceptable gate for every committed bill?"
    },
    {
      "cause": "De-identification missed a field (the shopper's name printed mid-table, a Nexus number, a Gmail thread id) and personal data reached the public repo.",
      "earliest_signal": "Any token from the PDF header (name, email, Nexus No, Bill No, Cashier ID) appears in the JSON.",
      "prevention": "Whitelist output fields rather than blacklisting inputs, and test that no header token from any source PDF appears in the committed JSON.",
      "interrogation_question": "May the test read the local PDFs to extract header tokens, given the PDFs are git-ignored and only on this machine?"
    },
    {
      "cause": "Judges saw Keells prices labeled source: receipt beside fictional Cargills, SPAR, and Glomark prices and concluded the comparison was rigged in Cargills' or Keells' favour.",
      "earliest_signal": "The day plan always or never picks Keells regardless of offers.",
      "prevention": "Label every price source on screen, set fictional prices within a realistic band around the observed Keells price, and show one case where Keells wins and one where it loses.",
      "interrogation_question": "Should fictional prices at other stores sit within plus or minus 10 percent of the observed Keells price?"
    },
    {
      "cause": "Cadence from median gaps flagged items as due that the shopper buys irregularly (papaya, carrots), so the pantry list looked wrong to the real shopper in the demo.",
      "earliest_signal": "Items with fewer than four purchases or very spread gaps appear as due.",
      "prevention": "Require at least three purchase dates for a due status and show the dates; mark irregular items as soon at most.",
      "interrogation_question": "Is three purchase dates the right minimum before an item can be marked due?"
    },
    {
      "cause": "OR-Tools added a large wheel; the Cloud Run build or cold start slowed, and CP-SAT with multiple workers produced different but equal-cost plans between runs, so the video and the live app disagreed.",
      "earliest_signal": "Two identical planner calls return different store assignments.",
      "prevention": "Run CP-SAT with one worker and a fixed seed, add a deterministic tie-break (fewer stores, then usual store, then store id), and test repeatability.",
      "interrogation_question": "Is a deterministic tie-break of fewer stores, then usual store, then store id acceptable?"
    },
    {
      "cause": "The UX rewrite replaced the v1 page and broke frozen v1 guest-page tests and judge controls, forcing late test edits that weakened guarantees.",
      "earliest_signal": "Any v1 guest-page test fails after the v2 page lands.",
      "prevention": "Serve v2 at / and keep the v1 flow at /v1 with its tests unchanged, or explicitly retire v1 page tests in a ticket the human approves.",
      "interrogation_question": "Keep v1 reachable at /v1 so its tests stay frozen, or retire the v1 page?"
    },
    {
      "cause": "trip_cost_lkr defaulted to 250 and the planner split baskets for savings the shopper would never travel for, which judges read as impractical.",
      "earliest_signal": "Demo plans split across two stores for savings under a few hundred rupees.",
      "prevention": "Show the trip cost on the plan, default it from the shopper's own setting, and show the single-store alternative beside any split.",
      "interrogation_question": "Is LKR 250 per extra store visit a reasonable default for Colombo?"
    },
    {
      "cause": "The agent's new plan_day tool let Gemini choose a different day or wallet than the shopper confirmed, so the Why step explained a plan that was not on screen.",
      "earliest_signal": "Agent tool arguments differ from the confirmed day or wallet.",
      "prevention": "The page passes the already computed plan JSON to the agent for explanation, and plan_day only reads confirmed inputs.",
      "interrogation_question": "Should the agent ever re-plan, or only explain the plan the engine already produced?"
    }
  ]
}

