  "causes": [
    {
      "cause": "Ten v2.1 features consumed 18 Oct; billing opened late, the Cloud Run deploy, deck, and video were rushed, and the entry missed mandatory deliverables although SC-018 was already working.",
      "earliest_signal": "SC-019 build tickets still open after midday Colombo time, or billing reopened with no deploy started.",
      "prevention": "Fix a hard cut-off hour; build in priority order (date fix, wizard, real offers, 4 stores, multi-buy, add item, receipt upload, suggestions, mock endpoints, delivery); whatever is not green by the cut-off is dropped; the accepted SC-018 build is the deploy safety net.",
      "interrogation_question": "What is the hard cut-off hour on 18 Oct after which unfinished v2.1 tickets are dropped and the last green build is deployed?"
    },
    {
      "cause": "A transcription slip in the real bank offers (Commercial Bank Keells on Sunday instead of Saturday, NTB rate 15% vs 25%) put a false claim about a named bank on the judged page.",
      "earliest_signal": "An offer row whose weekday, rate, or valid_to does not match the captured headline text stored beside it.",
      "prevention": "Store the captured headline sentence in each row and test that weekday, rate, and valid_to parse out of that sentence (AC8).",
      "interrogation_question": "For 'up to 25%' headlines, apply the full 25% (labeled 'up to') or a lower assumed rate?"
    },
    {
      "cause": "The wizard carried state in hidden fields; Back reset the pantry checks or the wallet, so judges saw their choices vanish and the plan change.",
      "earliest_signal": "A Back then Next round trip renders a different plan total for unchanged inputs.",
      "prevention": "One hidden-state serializer used by every step; AC3 asserts Back keeps choices.",
      "interrogation_question": "Is a stateless hidden-field wizard acceptable, or should the step state live in a signed cookie?"
    },
    {
      "cause": "A judge uploaded a real receipt that printed a card's last digits and a loyalty number; it went to Gemini and the extracted raw text was echoed into the page and hidden field.",
      "earliest_signal": "Uploaded receipt lines containing digits runs longer than an item code appear in receipt_json.",
      "prevention": "Only lines that map to a known history description are kept (existing _canonical_raw); raw text never reaches the agent; the image is never stored or logged; the existing extract rate limit applies.",
      "interrogation_question": "Allow receipt upload on the public judge URL, or keep it local-only and show only the sample receipt online?"
    },
    {
      "cause": "Four-store CP-SAT plans times a 7-day sweep times suggestion re-plans made the Plan step take tens of seconds on a cold Cloud Run instance, and judges left.",
      "earliest_signal": "Plan step over 3 seconds locally with max_stores 4.",
      "prevention": "Per-solve time limit, suggestions re-plan only the affected day, measure locally before deploy.",
      "interrogation_question": "Is 3 seconds an acceptable ceiling for the Plan step locally?"
    },
    {
      "cause": "Fixed-price promotions interacted with percent promotions and card eligibility so a line was discounted twice or the card offer used the shelf price, producing a wrong rupee figure.",
      "earliest_signal": "A bill whose promotion savings plus card discount exceed the shelf total minus the bill total.",
      "prevention": "Best single promotion per line, card on promoted price; AC7 plus the existing savings-equal-baseline-minus-plan test.",
      "interrogation_question": "When a fixed price and a percent promotion both apply to one line, take the one that saves more?"
    },
    {
      "cause": "Editing planner.py, pantry.py, and fixtures/v2 while SC-018 and SC-012 were open tripped the trust-root tier again, and P5 stalled on cross-model review at the deadline.",
      "earliest_signal": "Rails-guard or tier warnings on the first v2.1 build ticket.",
      "prevention": "Accept and complete SC-018 before decomposing SC-019; activate v2.1 tickets with rails only over completed work.",
      "interrogation_question": "Will you accept SC-018 (P6) now so SC-019 can build on it?"
    },
    {
      "cause": "Mock partner endpoints and the delivery step were read as real Keells, Cargills, Uber, or PickMe integrations, implying affiliation.",
      "earliest_signal": "Any mock response or delivery text without the word MOCK and the no-integration sentence.",
      "prevention": "Every mock response carries mock: true and the data label; AC10 and AC11 assert the wording.",
      "interrogation_question": "Is the delivery fee default of LKR 350 per bill acceptable as a labeled assumption?"
    }
  ]
}

